def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    probabilities = list(map(float, data[1:n+1]))

    def probability_of_not_upset(probs):
        # Calculate the probability of getting exactly one problem
        prob_one_problem = 0.0
        for i in range(1, 1 << len(probs)):
            prob = 1.0
            count = 0
            for j in range(len(probs)):
                if i & (1 << j):
                    prob *= probs[j]
                    count += 1
            if count == 1:
                prob_one_problem += prob
        return prob_one_problem

    result = probability_of_not_upset(probabilities)
    print(f"{result:.12f}")

