def max_probability_not_upset(n, probabilities):
    from itertools import combinations

    max_probability = 0.0

    for r in range(1, n + 1):
        for combo in combinations(range(n), r):
            p_ask = 1.0
            p_not_ask = 1.0
            for i in range(n):
                if i in combo:
                    p_ask *= probabilities[i]
                else:
                    p_not_ask *= (1 - probabilities[i])
            max_probability = max(max_probability, p_ask * p_not_ask)

    return max_probability

